<script lang="ts">
  import { CalendarDays, Check, ChevronRight, CirclePlus, Swords, Trophy } from '@lucide/svelte'
  import { store } from '../lib/store.svelte'
  import type { MatchRecord, ModalKind } from '../lib/types'
  import { birdName, formatDate } from '../lib/utils'
  let { open, notify }: { open: (kind: ModalKind) => void; notify: (message: string) => void } = $props()
  let tab = $state<'matches' | 'bracket'>('matches')
  let editing = $state('')
  let result = $state<'A' | 'B' | 'Draw'>('A')
  let upcoming = $derived(store.matches.filter(item => item.outcome === 'Pending'))
  let completed = $derived(store.matches.filter(item => item.outcome !== 'Pending'))
  let rounds = $derived([...new Set(store.matches.map(item => item.round))].sort((a, b) => a - b))
  function saveOutcome(match: MatchRecord) {
    store.setMatchOutcome(match.id, result === 'Draw' ? 'Draw' : result === 'A' ? 'Win' : 'Loss', result === 'Draw' ? '' : result === 'A' ? match.birdAId : match.birdBId)
    editing = ''
    notify('Match outcome recorded')
  }
</script>
<div class="page-stack"><div class="page-heading"><div><p class="kicker">Events & matches</p><h1>Every match, accounted for</h1><p class="page-lead">Plan dates, record outcomes, and follow the bracket.</p></div><div class="heading-actions"><button class="secondary-button" onclick={() => { tab = 'bracket'; notify('Bracket generated from scheduled matches') }}><Trophy size={17} /> Generate bracket</button><button class="primary-button" onclick={() => open('match')}><CirclePlus size={18} /> Schedule match</button></div></div>
  <div class="tab-list" role="tablist" aria-label="Match views"><button role="tab" aria-selected={tab === 'matches'} class:current={tab === 'matches'} onclick={() => tab = 'matches'}><Swords size={17} /> Matches</button><button role="tab" aria-selected={tab === 'bracket'} class:current={tab === 'bracket'} onclick={() => tab = 'bracket'}><Trophy size={17} /> Tournament bracket</button></div>
  {#if tab === 'matches'}<div class="detail-columns"><section class="panel"><div class="section-header compact"><div><h2>Upcoming</h2><p>{upcoming.length} match{upcoming.length === 1 ? '' : 'es'} scheduled</p></div></div>{#each upcoming as match}<article class="match-card"><div class="match-card-head"><span><CalendarDays size={15} /> {formatDate(match.date)}</span><span class="tag">Round {match.round}</span></div><h3>{match.eventName}</h3><div class="match-pair"><span>{birdName(store.birds, match.birdAId)}</span><strong>VS</strong><span>{birdName(store.birds, match.birdBId)}</span></div>{#if editing === match.id}<div class="result-editor"><label><span>Result</span><select bind:value={result}><option value="A">{birdName(store.birds, match.birdAId)} wins</option><option value="B">{birdName(store.birds, match.birdBId)} wins</option><option value="Draw">Draw</option></select></label><button class="primary-button" onclick={() => saveOutcome(match)}><Check size={16} /> Save result</button></div>{:else}<button class="text-button" onclick={() => { editing = match.id; result = 'A' }}>Record outcome <ChevronRight size={16} /></button>{/if}</article>{:else}<p class="muted-note">No upcoming matches. Schedule one to get started.</p>{/each}</section>
  <section class="panel"><div class="section-header compact"><div><h2>Completed</h2><p>Recent results and records.</p></div></div>{#each completed as match}<article class="match-card"><div class="match-card-head"><span><CalendarDays size={15} /> {formatDate(match.date)}</span><span class="status-pill active">{match.outcome === 'Draw' ? 'Draw' : 'Final'}</span></div><h3>{match.eventName}</h3><div class="match-pair"><span class:winner={match.winnerId === match.birdAId}>{birdName(store.birds, match.birdAId)}</span><strong>VS</strong><span class:winner={match.winnerId === match.birdBId}>{birdName(store.birds, match.birdBId)}</span></div><p class="muted-note">{match.outcome === 'Draw' ? 'Draw' : birdName(store.birds, match.winnerId) + ' won'} · Round {match.round}</p></article>{:else}<p class="muted-note">Results will appear here after a match is recorded.</p>{/each}</section></div>
  {:else}<section class="panel bracket-panel"><div class="section-header compact"><div><h2>Tournament bracket</h2><p>Matches grouped by round; outcomes update here automatically.</p></div></div><div class="bracket-board">{#each rounds as round}<div class="bracket-round"><h3>Round {round}</h3>{#each store.matches.filter(item => item.round === round) as match}<div class="bracket-match"><span>{match.eventName}</span><div class:winner={match.winnerId === match.birdAId}>{birdName(store.birds, match.birdAId)} {#if match.winnerId === match.birdAId}<Trophy size={14} />{/if}</div><div class:winner={match.winnerId === match.birdBId}>{birdName(store.birds, match.birdBId)} {#if match.winnerId === match.birdBId}<Trophy size={14} />{/if}</div><small>{match.outcome === 'Pending' ? formatDate(match.date) : match.outcome}</small></div>{/each}</div>{/each}</div></section>{/if}
</div>
